reference.src/duration.js:
const UNITS = { ms: 1, s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 };
export function parseDuration(text) {
  if (typeof text !== 'string' || !/^(\d+(ms|s|m|h|d))+$/.test(text)) throw new TypeError(`invalid duration: ${text}`);
  let total = 0;
  for (const [, n, unit] of text.matchAll(/(\d+)(ms|s|m|h|d)/g)) total += Number(n) * UNITS[unit];
  return total;
}

